package com.example.library.infrastructure.loan;

import com.example.library.domain.loan.Isbn;
import com.example.library.domain.loan.Loan;
import com.example.library.domain.loan.LoanRepository;
import com.example.library.domain.loan.MemberId;

public class JpaLoanRepository implements LoanRepository {

    private final SpringDataLoanRepository jpa;

    JpaLoanRepository(SpringDataLoanRepository jpa) {
        this.jpa = jpa;
    }

    public static JpaLoanRepository create(SpringDataLoanRepository jpa) {
        return new JpaLoanRepository(jpa);
    }

    @Override
    public void save(Loan loan) {
        jpa.saveAndFlush(new LoanEntity(loan.id().value(), loan.memberId().value(),
                loan.isbn().value(), loan.borrowedAt()));
    }

    @Override
    public int countByMember(MemberId memberId) {
        return jpa.countByMemberId(memberId.value());
    }

    @Override
    public boolean existsByIsbn(Isbn isbn) {
        return jpa.existsByIsbn(isbn.value());
    }
}
